USE [CodePilot];
SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRY
    BEGIN TRANSACTION;

    CREATE TABLE #NinjaTraderRagImport
    (
        Title nvarchar(255) COLLATE DATABASE_DEFAULT NOT NULL,
        FilePath nvarchar(500) COLLATE DATABASE_DEFAULT NULL,
        Language nvarchar(50) COLLATE DATABASE_DEFAULT NULL,
        Category nvarchar(50) COLLATE DATABASE_DEFAULT NULL,
        Tags nvarchar(255) COLLATE DATABASE_DEFAULT NULL,
        Content nvarchar(max) COLLATE DATABASE_DEFAULT NOT NULL,
        Embedding nvarchar(max) COLLATE DATABASE_DEFAULT NOT NULL,
        Description nvarchar(500) COLLATE DATABASE_DEFAULT NULL,
        RagLevel nvarchar(20) COLLATE DATABASE_DEFAULT NOT NULL,
        PlatformId tinyint NOT NULL
    );

    INSERT INTO #NinjaTraderRagImport
    (Title, FilePath, Language, Category, Tags, Content, Embedding, Description, RagLevel, PlatformId)
    VALUES
    (N'NinjaTrader Chart Button Market Order', N'NinjaTraderChartButtonMarketOrder.cs', N'C#', N'Strategy', N'NinjaTrader, NinjaScript, Strategy, Chart Button, WPF, Market Order, EnterLong, Custom Controls, Order Entry', N'//
// Based on the NinjaTrader Chart Order Buttons strategy example.
//
#region Using declarations
using System.Windows;
using System.Windows.Media;
using NinjaTrader.Gui.Chart;
#endregion

namespace NinjaTrader.NinjaScript.Strategies.OrderManagementExamples
{
	public class NinjaTraderChartButtonMarketOrder : Strategy
	{
		private System.Windows.Controls.Grid buttonsGrid;
		private System.Windows.Controls.Button longMarketButton;

		protected override void OnStateChange()
		{
			if (State == State.SetDefaults)
			{
				Description			= @"Demonstrates submitting a market order from a custom WPF chart button.";
				Name				= "NinjaTraderChartButtonMarketOrder";
				Calculate			= Calculate.OnPriceChange;
				EntriesPerDirection	= int.MaxValue;
			}
			else if (State == State.DataLoaded)
			{
				if (ChartControl != null)
					CreateWPFControls();
			}
			else if (State == State.Terminated)
			{
				if (ChartControl != null)
					RemoveWPFControls();
			}
		}

		private void CreateWPFControls()
		{
			ChartControl.Dispatcher.InvokeAsync(() =>
			{
				if (buttonsGrid != null && UserControlCollection.Contains(buttonsGrid))
					return;

				buttonsGrid = new System.Windows.Controls.Grid
				{
					Background			= Brushes.Red,
					Name				= "MarketOrderButtonsGrid",
					HorizontalAlignment	= HorizontalAlignment.Right,
					VerticalAlignment	= VerticalAlignment.Top
				};

				longMarketButton = new System.Windows.Controls.Button
				{
					Name		= "LongMarketButton",
					Content		= "Long market order",
					Foreground	= Brushes.White,
					Background	= Brushes.Green
				};

				longMarketButton.Click += OnButtonClick;
				buttonsGrid.Children.Add(longMarketButton);
				UserControlCollection.Add(buttonsGrid);
			});
		}

		private void OnButtonClick(object sender, RoutedEventArgs e)
		{
			if (sender != longMarketButton)
				return;

			// Synchronize the UI event with NinjaScript''s data thread.
			TriggerCustomEvent(o => EnterLong("Long market"), null);
		}

		private void RemoveWPFControls()
		{
			ChartControl.Dispatcher.InvokeAsync(() =>
			{
				if (longMarketButton != null)
				{
					longMarketButton.Click -= OnButtonClick;
					longMarketButton = null;
				}

				if (buttonsGrid != null)
				{
					UserControlCollection.Remove(buttonsGrid);
					buttonsGrid = null;
				}
			});
		}
	}
}
