    (N'NinjaTrader Chart Button Dynamic Limit Order', N'NinjaTraderChartButtonDynamicLimitOrder.cs', N'C#', N'Strategy', N'NinjaTrader, NinjaScript, Strategy, Chart Button, WPF, Limit Order, SMA, OnOrderUpdate, CancelOrder, Dynamic Price', N'//
// Based on the NinjaTrader Chart Order Buttons strategy example.
//
#region Using declarations
using System;
using System.Windows;
using System.Windows.Media;
using NinjaTrader.Cbi;
using NinjaTrader.Gui.Chart;
using NinjaTrader.NinjaScript.DrawingTools;
using NinjaTrader.NinjaScript.Indicators;
#endregion

namespace NinjaTrader.NinjaScript.Strategies.OrderManagementExamples
{
	public class NinjaTraderChartButtonDynamicLimitOrder : Strategy
	{
		private System.Windows.Controls.Grid buttonsGrid;
		private System.Windows.Controls.Button longLimitButton;
		private bool longLimitEnabled;
		private Order longLimitOrder;
		private SMA sma;

		protected override void OnStateChange()
		{
			if (State == State.SetDefaults)
			{
				Description			= @"Demonstrates submitting and updating a limit order from a custom WPF chart button.";
				Name				= "NinjaTraderChartButtonDynamicLimitOrder";
				Calculate			= Calculate.OnPriceChange;
				EntriesPerDirection	= int.MaxValue;
			}
			else if (State == State.DataLoaded)
			{
				sma = SMA(14);
				AddChartIndicator(sma);
				longLimitEnabled = false;

				if (ChartControl != null)
					CreateWPFControls();
			}
			else if (State == State.Terminated)
			{
				if (ChartControl != null)
					RemoveWPFControls();
			}
		}

		protected override void OnBarUpdate()
		{
			if (longLimitOrder != null
				&& (longLimitOrder.OrderState == OrderState.Working
					|| longLimitOrder.OrderState == OrderState.Accepted))
			{
				double limitPrice = Math.Min(
					Instrument.MasterInstrument.RoundToTickSize(sma[0]),
					GetCurrentAsk() - TickSize);

				EnterLongLimit(limitPrice, "Long limit");
			}
		}

		protected override void OnOrderUpdate(Order order, double limitPrice, double stopPrice,
			int quantity, int filled, double averageFillPrice, OrderState orderState,
			DateTime time, ErrorCode error, string comment)
		{
			if (order.Name != "Long limit")
				return;

			longLimitOrder = order;

			if (orderState == OrderState.Working || orderState == OrderState.Accepted)
			{
				Draw.TextFixed(this, "infoBox", "Limit order working at: " + limitPrice,
					TextPosition.BottomLeft);
				SetButtonAppearance("Cancel limit", Brushes.LightGreen, Brushes.Black);
			}
			else if (orderState == OrderState.Cancelled
				|| orderState == OrderState.Rejected
				|| orderState == OrderState.Filled)
			{
				if (orderState == OrderState.Filled)
					Draw.TextFixed(this, "infoBox", "Limit filled at: " + averageFillPrice,
						TextPosition.BottomLeft);
				else if (orderState == OrderState.Cancelled)
					Draw.TextFixed(this, "infoBox", "Limit cancelled", TextPosition.BottomLeft);

				longLimitEnabled = false;
				longLimitOrder = null;
				SetButtonAppearance("Long limit at indicator price", Brushes.Green, Brushes.White);
			}
		}

		private void CreateWPFControls()
		{
			ChartControl.Dispatcher.InvokeAsync(() =>
			{
				if (buttonsGrid != null && UserControlCollection.Contains(buttonsGrid))
					return;

				buttonsGrid = new System.Windows.Controls.Grid
				{
					Background			= Brushes.Red,
					Name				= "DynamicLimitOrderButtonsGrid",
					HorizontalAlignment	= HorizontalAlignment.Right,
					VerticalAlignment	= VerticalAlignment.Top
				};

				longLimitButton = new System.Windows.Controls.Button
				{
					Name		= "LongLimitButton",
					Content		= "Long limit at indicator price",
					Foreground	= Brushes.White,
					Background	= Brushes.Green
				};

				longLimitButton.Click += OnButtonClick;
				buttonsGrid.Children.Add(longLimitButton);
				UserControlCollection.Add(buttonsGrid);
			});
		}

		private void OnButtonClick(object sender, RoutedEventArgs e)
		{
			if (sender != longLimitButton)
				return;

			longLimitEnabled = !longLimitEnabled;

			TriggerCustomEvent(o =>
			{
				if (longLimitEnabled && longLimitOrder == null)
				{
					double limitPrice = Math.Min(
						Instrument.MasterInstrument.RoundToTickSize(sma[0]),
						GetCurrentAsk() - TickSize);

					EnterLongLimit(0, true, 1, limitPrice, "Long limit");
				}
				else if (!longLimitEnabled && longLimitOrder != null
					&& (longLimitOrder.OrderState == OrderState.Working
						|| longLimitOrder.OrderState == OrderState.Accepted))
				{
					CancelOrder(longLimitOrder);
				}
			}, null);

			SetButtonAppearance(
				longLimitEnabled ? "Limit submitted" : "Long limit at indicator price",
				longLimitEnabled ? Brushes.LightGreen : Brushes.Green,
				longLimitEnabled ? Brushes.Black : Brushes.White);
		}

		private void SetButtonAppearance(string content, Brush background, Brush foreground)
		{
			if (ChartControl == null || longLimitButton == null)
				return;

			ChartControl.Dispatcher.InvokeAsync(() =>
			{
				longLimitButton.Content = content;
				longLimitButton.Background = background;
				longLimitButton.Foreground = foreground;
			});
		}

		private void RemoveWPFControls()
		{
			ChartControl.Dispatcher.InvokeAsync(() =>
			{
				if (longLimitButton != null)
				{
					longLimitButton.Click -= OnButtonClick;
					longLimitButton = null;
				}

				if (buttonsGrid != null)
				{
					UserControlCollection.Remove(buttonsGrid);
					buttonsGrid = null;
				}
			});
		}
