    (N'NinjaTrader Chart Button Conditional Order', N'NinjaTraderChartButtonConditionalOrder.cs', N'C#', N'Strategy', N'NinjaTrader, NinjaScript, Strategy, Chart Button, WPF, Conditional Order, SMA Cross, EnterLong, Custom Controls', N'//
// Based on the NinjaTrader Chart Order Buttons strategy example.
//
#region Using declarations
using System.Windows;
using System.Windows.Media;
using NinjaTrader.Gui.Chart;
using NinjaTrader.NinjaScript.DrawingTools;
using NinjaTrader.NinjaScript.Indicators;
#endregion

namespace NinjaTrader.NinjaScript.Strategies.OrderManagementExamples
{
	public class NinjaTraderChartButtonConditionalOrder : Strategy
	{
		private System.Windows.Controls.Grid buttonsGrid;
		private System.Windows.Controls.Button longConditionalButton;
		private bool longConditionTriggerEnabled;
		private SMA sma;

		protected override void OnStateChange()
		{
			if (State == State.SetDefaults)
			{
				Description			= @"Demonstrates arming a conditional market order from a custom WPF chart button.";
				Name				= "NinjaTraderChartButtonConditionalOrder";
				Calculate			= Calculate.OnPriceChange;
				EntriesPerDirection	= int.MaxValue;
			}
			else if (State == State.DataLoaded)
			{
				sma = SMA(14);
				AddChartIndicator(sma);
				longConditionTriggerEnabled = false;

				if (ChartControl != null)
					CreateWPFControls();
			}
			else if (State == State.Terminated)
			{
				if (ChartControl != null)
					RemoveWPFControls();
			}
		}

		protected override void OnBarUpdate()
		{
			if (!longConditionTriggerEnabled)
				return;

			// Example condition: the SMA crosses the market price.
			if (CrossAbove(sma, Close, 1) || CrossBelow(sma, Close, 1))
			{
				longConditionTriggerEnabled = false;
				EnterLong("Long conditional");
				SetButtonAppearance("Long after condition", Brushes.Green, Brushes.White);
				Draw.TextFixed(this, "infoBox",
					"SMA has crossed the market price; order submitted.",
					TextPosition.BottomLeft);
			}
		}

		private void CreateWPFControls()
		{
			ChartControl.Dispatcher.InvokeAsync(() =>
			{
				if (buttonsGrid != null && UserControlCollection.Contains(buttonsGrid))
					return;

				buttonsGrid = new System.Windows.Controls.Grid
				{
					Background			= Brushes.Red,
					Name				= "ConditionalOrderButtonsGrid",
					HorizontalAlignment	= HorizontalAlignment.Right,
					VerticalAlignment	= VerticalAlignment.Top
				};

				longConditionalButton = new System.Windows.Controls.Button
				{
					Name		= "LongConditionalButton",
					Content		= "Long after condition",
					Foreground	= Brushes.White,
					Background	= Brushes.Green
				};

				longConditionalButton.Click += OnButtonClick;
				buttonsGrid.Children.Add(longConditionalButton);
				UserControlCollection.Add(buttonsGrid);
			});
		}

		private void OnButtonClick(object sender, RoutedEventArgs e)
		{
			if (sender != longConditionalButton)
				return;

			TriggerCustomEvent(o =>
			{
				longConditionTriggerEnabled = !longConditionTriggerEnabled;

				string message = longConditionTriggerEnabled
					? "Condition trigger enabled. An entry will be placed when the SMA crosses the market price."
					: "Condition trigger disabled.";

				Draw.TextFixed(this, "infoBox", message, TextPosition.BottomLeft);
			}, null);

			SetButtonAppearance(
				!longConditionTriggerEnabled ? "Condition enabled" : "Long after condition",
				!longConditionTriggerEnabled ? Brushes.LightGreen : Brushes.Green,
				!longConditionTriggerEnabled ? Brushes.Black : Brushes.White);

			ForceRefresh();
		}

		private void SetButtonAppearance(string content, Brush background, Brush foreground)
		{
			if (ChartControl == null || longConditionalButton == null)
				return;

			ChartControl.Dispatcher.InvokeAsync(() =>
			{
				longConditionalButton.Content = content;
				longConditionalButton.Background = background;
				longConditionalButton.Foreground = foreground;
			});
		}

		private void RemoveWPFControls()
		{
			ChartControl.Dispatcher.InvokeAsync(() =>
			{
				if (longConditionalButton != null)
				{
					longConditionalButton.Click -= OnButtonClick;
					longConditionalButton = null;
				}

				if (buttonsGrid != null)
				{
					UserControlCollection.Remove(buttonsGrid);
					buttonsGrid = null;
				}
			});
		}
