    (N'Session-Aware Intraday Trading Strategy', N'SessionAwareIntradayExample.cs', N'C#', N'Strategy', N'intraday strategy, SessionIterator, IsFirstBarOfSession, trading hours, session reset, daily trade limit, ExitOnSessionCloseStrategy, time filter', N'#region Using declarations
using System;
using System.ComponentModel.DataAnnotations;
using NinjaTrader.Cbi;
using NinjaTrader.Data;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class SessionAwareIntradayExample : Strategy
    {
        private SessionIterator sessionIterator;
        private DateTime tradingDay;
        private int tradesThisSession;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "SessionAwareIntradayExample";
                Calculate = Calculate.OnBarClose;
                IsExitOnSessionCloseStrategy = true;
                ExitOnSessionCloseSeconds = 30;
                StartTime = 93000;
                EndTime = 153000;
                MaximumTradesPerSession = 1;
            }
            else if (State == State.DataLoaded)
            {
                sessionIterator = new SessionIterator(Bars);
            }
        }

        protected override void OnBarUpdate()
        {
            if (!Bars.BarsType.IsIntraday || CurrentBar < 20)
                return;

            DateTime barTradingDay = sessionIterator.GetTradingDay(Time[0]);
            if (Bars.IsFirstBarOfSession || barTradingDay != tradingDay)
            {
                tradingDay = barTradingDay;
                tradesThisSession = 0;
            }

            int barTime = ToTime(Time[0]);
            if (barTime < StartTime || barTime > EndTime)
                return;

            if (Position.MarketPosition == MarketPosition.Flat &&
                tradesThisSession < MaximumTradesPerSession &&
                CrossAbove(Close, SMA(20), 1))
            {
                EnterLong("SessionLong");
                tradesThisSession++;
            }
        }

        [Range(0, 235959), NinjaScriptProperty]
        [Display(Name = "Start time (HHmmss)", GroupName = "Session", Order = 0)]
        public int StartTime { get; set; }

        [Range(0, 235959), NinjaScriptProperty]
        [Display(Name = "End time (HHmmss)", GroupName = "Session", Order = 1)]
        public int EndTime { get; set; }

        [Range(1, int.MaxValue), NinjaScriptProperty]
        [Display(Name = "Maximum trades per session", GroupName = "Session", Order = 2)]
        public int MaximumTradesPerSession { get; set; }
    }
