65,0.017318726,0.014152527,-0.00019741058,-0.025543213,0.031036377,-0.012298584,-0.003742218,0.033172607,0.001294136,-0.009635925,-0.0026950836,-0.016616821,-0.0256958,0.03604126,0.010429382,-0.011383057,-0.00030946732,-0.0036373138,0.009635925,-0.04925537,-0.01852417,0.009757996,0.017837524,-0.020202637,-0.004180908,0.025802612,-0.009841919,0.0057029724,0.01802063,-0.024108887,0.008918762,-0.0088272095,0.02180481,0.011161804,0.0018186569,0.017303467,0.036132812,-0.0056533813,0.010604858,-0.025314331,0.060913086,0.033172607,-0.006034851,-0.00046277046,0.016342163,-0.02809143,0.009346008,5.877018E-05,0.016326904,-0.008628845,-0.014328003,0.0076141357,-0.0039863586,-0.037322998,0.014480591,0.019866943,0.03427124,0.021255493,-0.003572464,-0.006061554,-0.019744873,0.0098724365,0.026123047,-0.0032691956,0.016326904,0.02279663,0.03137207,-0.017730713,-0.022460938,0.0026855469,-0.03982544,0.028930664,0.03744507,0.010772705,-0.025161743,-0.026733398,-0.021881104,0.00818634,0.019836426,-0.015075684,0.0016021729,0.02154541,0.029830933,0.03137207,0.009963989,-0.022369385,0.0052986145,0.02305603,-0.002773285,0.027450562,-0.013549805,-0.039367676,-0.024383545,-0.023590088,-0.007675171]', N'Creates a multi-timeframe strategy that trades the primary chart only when a secondary higher timeframe confirms the trend. Demonstrates series configuration, update routing and sufficient-bar validation.', N'Minimal', 2),
    (N'Partial Fill and Protective Order Handling', N'OrderExecutionHandlingExample.cs', N'C#', N'Strategy', N'OnOrderUpdate, OnExecutionUpdate, partial fills, rejected order, protective stop, profit target, OrderState, Execution, average fill price, order handling', N'#region Using declarations
using System;
using System.ComponentModel.DataAnnotations;
using System.Windows.Media;
using NinjaTrader.Cbi;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class OrderExecutionHandlingExample : Strategy
    {
        private Order entryOrder;
        private Order stopOrder;
        private Order targetOrder;
        private int entryFilled;
        private double entryFillValue;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "OrderExecutionHandlingExample";
                Calculate = Calculate.OnBarClose;
                StopLossTicks = 12;
                ProfitTargetTicks = 24;
            }
        }

        protected override void OnBarUpdate()
        {
            if (CurrentBar < 20 || Position.MarketPosition != MarketPosition.Flat || entryOrder != null)
                return;

            if (CrossAbove(Close, SMA(20), 1))
                EnterLong(2, "Entry");
        }

        protected override void OnOrderUpdate(
            Order order,
            double limitPrice,
            double stopPrice,
            int quantity,
            int filled,
            double averageFillPrice,
            OrderState orderState,
            DateTime time,
            ErrorCode error,
            string nativeError)
        {
            if (order.Name == "Entry")
                entryOrder = order;
            else if (order.Name == "ProtectiveStop")
                stopOrder = order;
            else if (order.Name == "ProfitTarget")
                targetOrder = order;

            if (orderState == OrderState.Rejected)
            {
                Print($"Order rejected: {order.Name}; error={error}; message={nativeError}");

                if (order == entryOrder)
                    entryOrder = null;
            }

            if (order == entryOrder &&
                (orderState == OrderState.Cancelled || orderState == OrderState.Filled) &&
                order.Filled == 0)
                entryOrder = null;
        }

        protected override void OnExecutionUpdate(
            Execution execution,
            string executionId,
            double price,
            int quantity,
            MarketPosition marketPosition,
            string orderId,
            DateTime time)
        {
            if (entryOrder == null || execution.Order != entryOrder)
                return;

            entryFillValue += price * quantity;
            entryFilled += quantity;
            double averageEntry = entryFillValue / entryFilled;

            stopOrder = ExitLongStopMarket(
                0,
                true,
                entryFilled,
                averageEntry - StopLossTicks * TickSize,
                "ProtectiveStop",
                "Entry");

            targetOrder = ExitLongLimit(
                0,
                true,
                entryFilled,
                averageEntry + ProfitTargetTicks * TickSize,
                "ProfitTarget",
                "Entry");

            if (execution.Order.OrderState == OrderState.Filled)
                entryOrder = null;
        }

        [Range(1, int.MaxValue), NinjaScriptProperty]
        [Display(Name = "Stop loss (ticks)", GroupName = "Risk", Order = 0)]
        public int StopLossTicks { get; set; }

        [Range(1, int.MaxValue), NinjaScriptProperty]
        [Display(Name = "Profit target (ticks)", GroupName = "Risk", Order = 1)]
        public int ProfitTargetTicks { get; set; }
    }
