    (N'Historical-to-Realtime Order Transition', N'RealtimeTransitionExample.cs', N'C#', N'Strategy', N'historical realtime transition, State.Transition, State.Realtime, GetRealtimeOrder, IsBacktestOrder, working order, order reference, strategy startup', N'#region Using declarations
using System;
using System.ComponentModel.DataAnnotations;
using NinjaTrader.Cbi;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class RealtimeTransitionExample : Strategy
    {
        private Order entryOrder;
        private bool transitionObserved;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "RealtimeTransitionExample";
                Calculate = Calculate.OnBarClose;
                IsWaitUntilFlat = false;
                EntryOffsetTicks = 4;
            }
            else if (State == State.Transition)
            {
                transitionObserved = true;
                Print("Strategy is transitioning from historical to real-time processing.");
            }
            else if (State == State.Realtime)
            {
                Print($"Real-time processing started; transition observed={transitionObserved}.");
            }
        }

        protected override void OnBarUpdate()
        {
            if (CurrentBar < 20 || entryOrder != null || Position.MarketPosition != MarketPosition.Flat)
                return;

            if (CrossAbove(Close, SMA(20), 1))
                EnterLongLimit(0, true, 1, Close[0] - EntryOffsetTicks * TickSize, "TransitionEntry");
        }

        protected override void OnOrderUpdate(
            Order order,
            double limitPrice,
            double stopPrice,
            int quantity,
            int filled,
            double averageFillPrice,
            OrderState orderState,
            DateTime time,
            ErrorCode error,
            string nativeError)
        {
            if (entryOrder != null && entryOrder.IsBacktestOrder && State == State.Realtime)
                entryOrder = GetRealtimeOrder(entryOrder);

            if (order.Name == "TransitionEntry")
                entryOrder = order;

            if (entryOrder == order &&
                orderState is OrderState.Filled or OrderState.Cancelled or OrderState.Rejected)
                entryOrder = null;
        }

        [Range(1, int.MaxValue), NinjaScriptProperty]
        [Display(Name = "Entry offset (ticks)", GroupName = "Parameters", Order = 0)]
        public int EntryOffsetTicks { get; set; }
    }
