,0.0044822693,-0.020370483,-0.037750244,-0.014183044,0.026748657,0.018081665,-0.010543823,-1.2218952E-05,0.033691406,-0.018722534,0.032989502,-0.0072135925,-0.034454346,0.023666382,0.011474609,-0.0036697388,-0.008628845,0.0112838745,0.0041046143,-0.023635864,-0.027511597,0.027282715,0.014335632,-0.024002075,0.004650116,0.024856567,0.028060913,-0.013572693,0.018203735,-0.0104904175,0.0028324127,0.0060272217,0.0034065247,-0.008377075,0.016571045,0.00598526,0.021514893,-0.013191223,0.017913818,0.0087509155,0.056274414,-0.0005931854,-0.0057296753,-0.03869629,0.02166748,-0.032348633,-0.024108887,0.00094509125,0.0050964355,-0.030838013,-0.010643005,2.5510788E-05,-0.00037908554,-0.0051460266,0.00374794,0.0013923645,0.0071029663,0.05340576,0.011795044,-0.028060913,-0.0028820038,0.015602112,0.03186035,-0.01965332,0.018554688,-0.0016613007,0.00598526,-0.010696411,-0.012786865,-0.020401001,-0.049835205,0.0018930435,0.012313843,-0.0052452087,-0.028884888,0.002664566,-0.0073509216,0.024734497,0.010543823,0.0026683807,-0.0016069412,-0.00630188,-0.003993988,-0.009552002,0.004547119,-0.011047363,0.031066895,-0.02684021,0.002708435,0.03765869,-0.010932922,-0.0013370514,-0.011009216,-0.006839752,-0.013031006]', N'Demonstrates preserving a working order when strategy processing changes from historical to real time. Converts a historical order reference with GetRealtimeOrder and clears terminal order states safely.', N'Minimal', 2),
    (N'Unmanaged Entry Stop Target and OCO Lifecycle', N'UnmanagedOrderLifecycleExample.cs', N'C#', N'Strategy', N'unmanaged strategy, IsUnmanaged, SubmitOrderUnmanaged, ChangeOrder, CancelOrder, OCO orders, stop market, profit target, order rejection, order lifecycle', N'#region Using declarations
using System;
using System.ComponentModel.DataAnnotations;
using NinjaTrader.Cbi;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class UnmanagedOrderLifecycleExample : Strategy
    {
        private Order entryOrder;
        private Order stopOrder;
        private Order targetOrder;
        private int entrySubmittedBar = -1;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "UnmanagedOrderLifecycleExample";
                Calculate = Calculate.OnBarClose;
                IsUnmanaged = true;
                StopLossTicks = 12;
                ProfitTargetTicks = 24;
                CancelEntryAfterBars = 3;
            }
        }

        protected override void OnBarUpdate()
        {
            if (CurrentBar < 20)
                return;

            if (entryOrder == null &&
                stopOrder == null &&
                targetOrder == null &&
                Position.MarketPosition == MarketPosition.Flat &&
                CrossAbove(Close, SMA(20), 1))
            {
                entrySubmittedBar = CurrentBar;
                entryOrder = SubmitOrderUnmanaged(
                    0,
                    OrderAction.Buy,
                    OrderType.Limit,
                    1,
                    GetCurrentBid(),
                    0,
                    string.Empty,
                    "Entry");
                return;
            }

            if (entryOrder is { OrderState: OrderState.Working })
            {
                if (CurrentBar - entrySubmittedBar >= CancelEntryAfterBars)
                    CancelOrder(entryOrder);
                else
                    ChangeOrder(entryOrder, entryOrder.Quantity, GetCurrentBid(), 0);
            }
        }

        protected override void OnExecutionUpdate(
            Execution execution,
            string executionId,
            double price,
            int quantity,
            MarketPosition marketPosition,
            string orderId,
            DateTime time)
        {
            if (entryOrder == null || execution.Order != entryOrder)
                return;

            string oco = Guid.NewGuid().ToString("N");
            stopOrder = SubmitOrderUnmanaged(
                0,
                OrderAction.Sell,
                OrderType.StopMarket,
                quantity,
                0,
                price - StopLossTicks * TickSize,
                oco,
                "Stop");

            targetOrder = SubmitOrderUnmanaged(
                0,
                OrderAction.Sell,
                OrderType.Limit,
                quantity,
                price + ProfitTargetTicks * TickSize,
                0,
                oco,
                "Target");
        }

        protected override void OnOrderUpdate(
            Order order,
            double limitPrice,
            double stopPrice,
            int quantity,
            int filled,
            double averageFillPrice,
            OrderState orderState,
            DateTime time,
            ErrorCode error,
            string nativeError)
        {
            if (orderState == OrderState.Rejected)
                Print($"Rejected order {order.Name}: {error}; {nativeError}");

            if (order == entryOrder &&
                orderState is OrderState.Filled or OrderState.Cancelled or OrderState.Rejected)
                entryOrder = null;

            if (order == stopOrder &&
                orderState is OrderState.Filled or OrderState.Cancelled or OrderState.Rejected)
                stopOrder = null;

            if (order == targetOrder &&
                orderState is OrderState.Filled or OrderState.Cancelled or OrderState.Rejected)
                targetOrder = null;
        }

        [Range(1, int.MaxValue), NinjaScriptProperty]
        [Display(Name = "Stop loss (ticks)", GroupName = "Risk", Order = 0)]
        public int StopLossTicks { get; set; }

        [Range(1, int.MaxValue), NinjaScriptProperty]
        [Display(Name = "Profit target (ticks)", GroupName = "Risk", Order = 1)]
        public int ProfitTargetTicks { get; set; }

        [Range(1, int.MaxValue), NinjaScriptProperty]
        [Display(Name = "Cancel entry after bars", GroupName = "Orders", Order = 2)]
        public int CancelEntryAfterBars { get; set; }
