    (N'Bid Ask Spread Filter and Limit Entry', N'BidAskOrderExample.cs', N'C#', N'Strategy', N'bid ask strategy, spread filter, GetCurrentBid, GetCurrentAsk, OnMarketData, limit entry, EnterLongLimit, CancelOrder, real-time market data, price validation', N'#region Using declarations
using System;
using System.ComponentModel.DataAnnotations;
using NinjaTrader.Cbi;
using NinjaTrader.Data;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
    public class BidAskOrderExample : Strategy
    {
        private Order entryOrder;
        private double lastBid;
        private double lastAsk;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "BidAskOrderExample";
                Calculate = Calculate.OnEachTick;
                MaximumSpreadTicks = 2;
            }
        }

        protected override void OnMarketData(MarketDataEventArgs marketDataUpdate)
        {
            if (marketDataUpdate.MarketDataType == MarketDataType.Bid)
                lastBid = marketDataUpdate.Price;
            else if (marketDataUpdate.MarketDataType == MarketDataType.Ask)
                lastAsk = marketDataUpdate.Price;
        }

        protected override void OnBarUpdate()
        {
            if (State == State.Historical || CurrentBar < 20)
                return;

            double bid = GetCurrentBid();
            double ask = GetCurrentAsk();
            if (bid <= 0 || ask <= 0)
                return;

            lastBid = bid;
            lastAsk = ask;
            double spreadTicks = (lastAsk - lastBid) / TickSize;

            if (entryOrder is { OrderState: OrderState.Working })
            {
                if (spreadTicks > MaximumSpreadTicks)
                    CancelOrder(entryOrder);
                return;
            }

            if (Position.MarketPosition == MarketPosition.Flat &&
                entryOrder == null &&
                spreadTicks <= MaximumSpreadTicks &&
                Close[0] > SMA(20)[0])
                EnterLongLimit(0, true, 1, lastBid, "BidEntry");
        }

        protected override void OnOrderUpdate(
            Order order,
            double limitPrice,
            double stopPrice,
            int quantity,
            int filled,
            double averageFillPrice,
            OrderState orderState,
            DateTime time,
            ErrorCode error,
            string nativeError)
        {
            if (order.Name == "BidEntry")
                entryOrder = order;

            if (entryOrder == order &&
                orderState is OrderState.Filled or OrderState.Cancelled or OrderState.Rejected)
                entryOrder = null;
        }

        [Range(0, double.MaxValue), NinjaScriptProperty]
        [Display(Name = "Maximum spread (ticks)", GroupName = "Orders", Order = 0)]
        public double MaximumSpreadTicks { get; set; }
    }
