    INSERT INTO #NinjaTraderRagImport
    (Title, FilePath, Language, Category, Tags, Content, Embedding, Description, RagLevel, PlatformId)
    VALUES
    (N'Williams Percent R Momentum Indicator', N'WilliamsR.cs', N'C#', N'Indicator', N'Williams %R indicator, Williams Percent R, momentum oscillator, overbought oversold, price range position, reversal signals, minus 25 minus 75, highest high, lowest low, range-bound market', N'
#region Using declarations
using System.ComponentModel.DataAnnotations;
using System.Windows.Media;
#endregion

// This namespace holds indicators in this folder and is required. Do not change it.
namespace NinjaTrader.NinjaScript.Indicators
{
	/// <summary>
	/// The Williams %R is a momentum indicator that is designed to identify overbought and oversold areas in a nontrending market.
	/// </summary>
	public class WilliamsR : Indicator
	{
		private MAX max;
		private MIN min;

		protected override void OnStateChange()
		{
			if (State == State.SetDefaults)
			{
				Description					= Custom.Resource.NinjaScriptIndicatorDescriptionWilliamsR;
				Name						= Custom.Resource.NinjaScriptIndicatorNameWilliamsR;
				IsSuspendedWhileInactive	= true;
				Period						= 14;

				AddLine(Brushes.DarkGray,	-25,	Custom.Resource.NinjaScriptIndicatorOverbought);
				AddLine(Brushes.DarkGray,	-75,	Custom.Resource.NinjaScriptIndicatorOversold);
				AddPlot(Brushes.Goldenrod,		Custom.Resource.WilliamsPercentR);
			}
			else if (State == State.DataLoaded)
			{
				max = MAX(High, Period);
				min	= MIN(Low, Period);
			}
		}

		protected override void OnBarUpdate()
		{
			double max0	= max[0];
			double min0	= min[0];
			Value[0]	= -100 * (max0 - Close[0]) / (max0 - min0 == 0 ? 1 : max0 - min0);
		}

		#region Properties
		[Range(1, int.MaxValue), NinjaScriptProperty]
		[Display(ResourceType = typeof(Custom.Resource), Name = "Period", GroupName = "NinjaScriptParameters", Order = 0)]
		public int Period { get; set; }
		#endregion
	}
}

