    INSERT INTO #NinjaTraderRagImport
    (Title, FilePath, Language, Category, Tags, Content, Embedding, Description, RagLevel, PlatformId)
    VALUES
    (N'Smart Money Market Structure with BOS and CHoCH', N'SmartMoneyStructure.cs', N'C#', N'Indicator', N'smart money concepts, SMC indicator, market structure, BOS, break of structure, CHoCH, change of character, swing high, swing low, strong low, weak high, bullish structure, bearish structure', N'#region Using declarations
using System;
using System.ComponentModel.DataAnnotations;
using System.Windows.Media;
using NinjaTrader.Gui;
using NinjaTrader.Gui.Chart;
using NinjaTrader.NinjaScript.DrawingTools;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class SmartMoneyMarketStructure : Indicator
    {
        private enum MarketTrend
        {
            Undefined,
            Bullish,
            Bearish
        }

        private MarketTrend trend;

        private double lastSwingHigh;
        private double lastSwingLow;

        private int lastSwingHighBar;
        private int lastSwingLowBar;

        private int brokenSwingHighBar;
        private int brokenSwingLowBar;

        private double strongLowPrice;
        private double weakHighPrice;

        private int strongLowBar;
        private int weakHighBar;

        private int structureEventId;

        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Smart Money Market Structure";
                Description =
                    "Identifies swing highs and lows, breaks of structure, " +
                    "changes of character, strong lows and weak highs.";

                Calculate = Calculate.OnBarClose;
                IsOverlay = true;
                DrawOnPricePanel = true;
                DisplayInDataBox = false;
                PaintPriceMarkers = false;
                IsSuspendedWhileInactive = true;
                ScaleJustification = ScaleJustification.Right;

                SwingLength = 5;
                ShowBreakOfStructure = true;
                ShowChangeOfCharacter = true;
                ShowStrongLow = true;
                ShowWeakHigh = true;
                LabelOffsetTicks = 3;
            }
            else if (State == State.Configure)
            {
                ResetStructureState();
            }
        }

        private void ResetStructureState()
        {
            trend = MarketTrend.Undefined;

            lastSwingHigh = double.MinValue;
            lastSwingLow = double.MaxValue;

            lastSwingHighBar = -1;
            lastSwingLowBar = -1;

            brokenSwingHighBar = -1;
            brokenSwingLowBar = -1;

            strongLowPrice = double.NaN;
            weakHighPrice = double.NaN;

            strongLowBar = -1;
            weakHighBar = -1;

            structureEventId = 0;
        }

        protected override void OnBarUpdate()
        {
            if (CurrentBar < SwingLength * 2)
                return;

            DetectConfirmedPivots();
            DetectStructureBreaks();
            DrawActiveLevels();
        }

        private void DetectConfirmedPivots()
        {
            int pivotBarsAgo = SwingLength;

            bool isSwingHigh = true;
            bool isSwingLow = true;

            double candidateHigh = High[pivotBarsAgo];
            double candidateLow = Low[pivotBarsAgo];

            for (int offset = 1; offset <= SwingLength; offset++)
            {
                if (candidateHigh <= High[pivotBarsAgo - offset]
                    || candidateHigh <= High[pivotBarsAgo + offset])
                {
                    isSwingHigh = false;
                }

                if (candidateLow >= Low[pivotBarsAgo - offset]
                    || candidateLow >= Low[pivotBarsAgo + offset])
                {
                    isSwingLow = false;
                }

                if (!isSwingHigh && !isSwingLow)
                    break;
            }

            int absolutePivotBar = CurrentBar - pivotBarsAgo;

            if (isSwingHigh)
            {
                lastSwingHigh = candidateHigh;
                lastSwingHighBar = absolutePivotBar;
            }

            if (isSwingLow)
            {
                lastSwingLow = candidateLow;
                lastSwingLowBar = absolutePivotBar;
            }
        }

        private void DetectStructureBreaks()
        {
            bool brokeSwingHigh =
                lastSwingHighBar >= 0
                && lastSwingHighBar != brokenSwingHighBar
                && Close[0] > lastSwingHigh;

            bool brokeSwingLow =
                lastSwingLowBar >= 0
                && lastSwingLowBar != brokenSwingLowBar
                && Close[0] < lastSwingLow;

            if (brokeSwingHigh)
            {
                ProcessBullishBreak();
                return;
            }

            if (brokeSwingLow)
                ProcessBearishBreak();
        }

        private void ProcessBullishBreak()
        {
            bool isChangeOfCharacter = trend == MarketTrend.Bearish;

            if (isChangeOfCharacter)
            {
                if (ShowChangeOfCharacter)
                {
                    DrawStructureEvent(
                        lastSwingHighBar,
                        lastSwingHigh,
                        true,
                        "CHoCH");
                }
            }
            else if (ShowBreakOfStructure)
            {
                DrawStructureEvent(
                    lastSwingHighBar,
                    lastSwingHigh,
                    true,
                    "BOS");
            }

            brokenSwingHighBar = lastSwingHighBar;
            trend = MarketTrend.Bullish;

            if (lastSwingLowBar >= 0)
            {
                strongLowPrice = lastSwingLow;
                strongLowBar = lastSwingLowBar;

                if (ShowStrongLow)
                    DrawStrongLowMarker();
            }
        }

        private void ProcessBearishBreak()
        {
            bool isChangeOfCharacter = trend == MarketTrend.Bullish;

            if (isChangeOfCharacter)
            {
                if (ShowChangeOfCharacter)
                {
                    DrawStructureEvent(
                        lastSwingLowBar,
                        lastSwingLow,
                        false,
                        "CHoCH");
                }
            }
            else if (ShowBreakOfStructure)
            {
                DrawStructureEvent(
                    lastSwingLowBar,
                    lastSwingLow,
                    false,
                    "BOS");
            }

            brokenSwingLowBar = lastSwingLowBar;
            trend = MarketTrend.Bearish;

            if (lastSwingHighBar >= 0)
            {
                weakHighPrice = lastSwingHigh;
                weakHighBar = lastSwingHighBar;

                if (ShowWeakHigh)
                    DrawWeakHighMarker();
            }
        }

        private void DrawStructureEvent(
            int levelBar,
            double levelPrice,
            bool bullish,
            string label)
        {
            int barsAgo = CurrentBar - levelBar;

            if (barsAgo < 0)
                return;

            Brush color = bullish ? Brushes.Teal : Brushes.Crimson;
            string tag = label + "_" + structureEventId++;

            Draw.Line(
                this,
                tag + "_Line",
                false,
                barsAgo,
                levelPrice,
                0,
                levelPrice,
                color,
                DashStyleHelper.Dash,
                2);

            int labelBarsAgo = barsAgo / 2;

            double labelPrice = bullish
                ? levelPrice + LabelOffsetTicks * TickSize
                : levelPrice - LabelOffsetTicks * TickSize;

            Draw.Text(
                this,
                tag + "_Label",
                false,
                label,
                labelBarsAgo,
                labelPrice,
                0,
                color,
                new Gui.Tools.SimpleFont("Arial", 10),
                System.Windows.TextAlignment.Center,
                Brushes.Transparent,
                Brushes.Transparent,
                0);
        }

        private void DrawStrongLowMarker()
        {
            int barsAgo = CurrentBar - strongLowBar;

            if (barsAgo < 0)
                return;

            Draw.ArrowUp(
                this,
                "StrongLowMarker_" + strongLowBar,
                false,
                barsAgo,
                strongLowPrice - LabelOffsetTicks * TickSize,
                Brushes.SeaGreen);

            Draw.Text(
                this,
                "StrongLowLabel_" + strongLowBar,
                "Strong Low",
                barsAgo,
                strongLowPrice - (LabelOffsetTicks + 4) * TickSize,
                Brushes.SeaGreen);
        }

        private void DrawWeakHighMarker()
        {
            int barsAgo = CurrentBar - weakHighBar;

            if (barsAgo < 0)
                return;

            Draw.ArrowDown(
                this,
                "WeakHighMarker_" + weakHighBar,
                false,
                barsAgo,
                weakHighPrice + LabelOffsetTicks * TickSize,
                Brushes.Crimson);

            Draw.Text(
                this,
                "WeakHighLabel_" + weakHighBar,
                "Weak High",
                barsAgo,
                weakHighPrice + (LabelOffsetTicks + 4) * TickSize,
                Brushes.Crimson);
        }

        private void DrawActiveLevels()
        {
            if (ShowStrongLow && strongLowBar >= 0)
            {
                Draw.Line(
                    this,
                    "ActiveStrongLow",
                    false,
                    CurrentBar - strongLowBar,
                    strongLowPrice,
                    0,
                    strongLowPrice,
                    Brushes.SeaGreen,
                    DashStyleHelper.Solid,
                    2);
            }

            if (ShowWeakHigh && weakHighBar >= 0)
            {
                Draw.Line(
                    this,
                    "ActiveWeakHigh",
                    false,
                    CurrentBar - weakHighBar,
                    weakHighPrice,
                    0,
                    weakHighPrice,
                    Brushes.Crimson,
                    DashStyleHelper.Solid,
                    2);
            }
        }

        #region Properties

        [Range(2, 50)]
        [NinjaScriptProperty]
        [Display(
            Name = "Swing Length",
            GroupName = "Parameters",
            Order = 0)]
        public int SwingLength { get; set; }

        [NinjaScriptProperty]
        [Display(
            Name = "Show Break of Structure",
            GroupName = "Parameters",
            Order = 1)]
        public bool ShowBreakOfStructure { get; set; }

        [NinjaScriptProperty]
        [Display(
            Name = "Show Change of Character",
            GroupName = "Parameters",
            Order = 2)]
        public bool ShowChangeOfCharacter { get; set; }

        [NinjaScriptProperty]
        [Display(
            Name = "Show Strong Low",
            GroupName = "Parameters",
            Order = 3)]
        public bool ShowStrongLow { get; set; }

        [NinjaScriptProperty]
        [Display(
            Name = "Show Weak High",
            GroupName = "Parameters",
            Order = 4)]
        public bool ShowWeakHigh { get; set; }

        [Range(1, 100)]
        [NinjaScriptProperty]
        [Display(
            Name = "Label Offset (ticks)",
            GroupName = "Parameters",
            Order = 5)]
        public int LabelOffsetTicks { get; set; }

