    (N'Volumetric Bar Delta and Delta Percentage', N'VolumetricBarDeltaExample.cs', N'C#', N'Indicator', N'volumetric bars, footprint indicator, order flow delta, bar delta, delta percentage, buying volume, selling volume, bid ask volume, VolumetricBarsType, order flow analysis, volume imbalance', N'#region Using declarations
using System.ComponentModel.DataAnnotations;
using System.Windows.Media;
using NinjaTrader.NinjaScript.BarsTypes;
using NinjaTrader.NinjaScript.DrawingTools;
#endregion

namespace NinjaTrader.NinjaScript.Indicators
{
    public class VolumetricBarDeltaExample : Indicator
    {
        protected override void OnStateChange()
        {
            if (State == State.SetDefaults)
            {
                Name = "Volumetric Bar Delta Example";
                Description = "Reads bid, ask and delta values from Volumetric bars.";
                Calculate = Calculate.OnBarClose;
                IsOverlay = false;
                IsSuspendedWhileInactive = true;
                AddPlot(Brushes.DodgerBlue, "BarDelta");
                AddPlot(Brushes.Goldenrod, "DeltaPercent");
                AddLine(Brushes.Gray, 0, "Zero");
            }
        }

        protected override void OnBarUpdate()
        {
            VolumetricBarsType volumetricBars =
                Bars?.BarsSeries?.BarsType as VolumetricBarsType;

            if (volumetricBars == null)
            {
                if (CurrentBar == 0)
                    Draw.TextFixed(this, "BarsTypeError",
                        "Apply this indicator to Volumetric bars.",
                        TextPosition.BottomRight);
                return;
            }

            long buyingVolume = volumetricBars.Volumes[CurrentBar].TotalBuyingVolume;
            long sellingVolume = volumetricBars.Volumes[CurrentBar].TotalSellingVolume;
            long barDelta = volumetricBars.Volumes[CurrentBar].BarDelta;
            long totalVolume = buyingVolume + sellingVolume;

            BarDelta[0] = barDelta;
            DeltaPercent[0] = totalVolume == 0
                ? 0
                : 100.0 * barDelta / totalVolume;
        }

        public Series<double> BarDelta => Values[0];
        public Series<double> DeltaPercent => Values[1];
    }
