    (N'EMA Crossover with Session and Risk Controls', N'EMATrend.cs', N'C#', N'Strategy', N'EMA crossover, session filter, overnight window, SetStopLoss, SetProfitTarget, EnterLong, EnterShort, position state, strategy parameters', N'#region Using declarations
using System;
using System.ComponentModel;
using System.ComponentModel.DataAnnotations;
using NinjaTrader.Cbi;
using NinjaTrader.NinjaScript;
using NinjaTrader.NinjaScript.Indicators;
using NinjaTrader.NinjaScript.Strategies;
#endregion

namespace NinjaTrader.NinjaScript.Strategies
{
	public class EmaTrendStrategy : Strategy
	{
		private EMA emaFast;
		private EMA emaSlow;

		[NinjaScriptProperty]
		[Display(Name = "Fast EMA Period", Description = "Period for the faster EMA.", Order = 1, GroupName = "EMA Parameters")]
		[Range(1, int.MaxValue)]
		public int FastEmaPeriod { get; set; }

		[NinjaScriptProperty]
		[Display(Name = "Slow EMA Period", Description = "Period for the slower EMA.", Order = 2, GroupName = "EMA Parameters")]
		[Range(1, int.MaxValue)]
		public int SlowEmaPeriod { get; set; }

		[NinjaScriptProperty]
		[Display(Name = "Stop Loss (ticks)", Description = "Fixed stop loss distance in ticks.", Order = 1, GroupName = "Risk Management")]
		[Range(1, int.MaxValue)]
		public int StopLossTicks { get; set; }

		[NinjaScriptProperty]
		[Display(Name = "Profit Target (ticks)", Description = "Fixed profit target distance in ticks.", Order = 2, GroupName = "Risk Management")]
		[Range(1, int.MaxValue)]
		public int ProfitTargetTicks { get; set; }

		[NinjaScriptProperty]
		[Display(Name = "Session Start", Description = "Earliest time of day for new entries.", Order = 1, GroupName = "Session Filter")]
		public TimeSpan SessionStart { get; set; }

		[NinjaScriptProperty]
		[Display(Name = "Session End", Description = "Latest time of day for new entries. Existing trades remain managed.", Order = 2, GroupName = "Session Filter")]
		public TimeSpan SessionEnd { get; set; }

		protected override void OnStateChange()
		{
			if (State == State.SetDefaults)
			{
				Description			= @"Trades EMA crossovers with a session filter, fixed stop loss and profit target.";
				Name				= "EmaTrendStrategy";
				Calculate			= Calculate.OnBarClose;
				EntriesPerDirection	= 1;
				DefaultQuantity		= 1;
				FastEmaPeriod		= 20;
				SlowEmaPeriod		= 50;
				StopLossTicks		= 20;
				ProfitTargetTicks	= 40;
				SessionStart		= new TimeSpan(9, 30, 0);
				SessionEnd			= new TimeSpan(16, 0, 0);

				SetStopLoss(CalculationMode.Ticks, StopLossTicks);
				SetProfitTarget(CalculationMode.Ticks, ProfitTargetTicks);
			}
			else if (State == State.DataLoaded)
			{
				emaFast = EMA(FastEmaPeriod);
				emaSlow = EMA(SlowEmaPeriod);

				AddChartIndicator(emaFast);
				AddChartIndicator(emaSlow);
			}
		}

		protected override void OnBarUpdate()
		{
			if (CurrentBar < 1)
				return;

			if (!IsInSession())
				return;

			if (Position.MarketPosition != MarketPosition.Flat)
				return;

			if (CrossAbove(emaFast, emaSlow, 1))
			{
				EnterLong(1, "Long");
			}
			else if (CrossBelow(emaFast, emaSlow, 1))
			{
				EnterShort(1, "Short");
			}
		}

		/// <summary>
		/// Returns true when the bar close time is inside the configured session window.
		/// Handles sessions that wrap past midnight if start time is later than end time.
		/// </summary>
		private bool IsInSession()
		{
			TimeSpan currentTime = Time[0].TimeOfDay;

			if (SessionStart < SessionEnd)
				return currentTime >= SessionStart && currentTime < SessionEnd;
			else
				return currentTime >= SessionStart || currentTime < SessionEnd;
		}
